// createThroughCore is CreateOne on the repository's transaction: input's row
// stamped, created by the behaviors' core, whose uses initialize the fields
// they own, with the columns the insert writes, and read back.
func (r *JobRepository) createThroughCore(ctx context.Context, input *JobCreate) (*types.Job, error) {
	row := input.row()
	columns, err := r.createColumns(row)
	if err != nil {
		return nil, err
	}
	opts := &rules.CreateOptions{ID: r.createKey(row), ExecuteOptions: rules.ExecuteOptions{OwnColumns: columns, Preconditions: behaviorPreconditions(ctx)}}
	key, err := rules.RunCreate(ctx, rulesHost(r.tx), "Job", r.coreOwn(row), behaviorCaller(ctx), opts)
	if err != nil {
		return nil, err
	}
	id, err := types.ParseIdentityUUID(key)
	if err != nil {
		return nil, fmt.Errorf("create Job: the core's key %q: %w", key, err)
	}
	return r.GetOne(ctx, id, nil)
}

// upsertInputs are inputs as an upsert inserts them (D103): each one's row
// with the fields its behaviors own as the core's create of it gives them,
// run to its change set and not applied, so the insert writes what CreateOne
// would have, and the update, which sets none of them, leaves them as the
// row holds them. A refusal of the core's is returned before anything is
// written.
func (r *JobRepository) upsertInputs(ctx context.Context, inputs []*JobCreate) ([]*types.Job, error) {
	host := rulesHost(r.tx)
	rows := make([]*types.Job, 0, len(inputs))
	for _, input := range inputs {
		row := input.row()
		owned, err := rules.PrepareCreate(ctx, host, "Job", r.coreOwn(row), behaviorCaller(ctx), &rules.CreateOptions{ID: r.createKey(row), ExecuteOptions: rules.ExecuteOptions{Preconditions: behaviorPreconditions(ctx)}})
		if err != nil {
			return nil, err
		}
		if value, ok := owned["Lease"]["holder"]; ok {
			if err := json.Unmarshal(value, &row.LeaseHolder); err != nil {
				return nil, fmt.Errorf("upsert Job: the core's Lease.holder %s: %w", value, err)
			}
		}
		if value, ok := owned["Lease"]["token"]; ok {
			if err := json.Unmarshal(value, &row.LeaseToken); err != nil {
				return nil, fmt.Errorf("upsert Job: the core's Lease.token %s: %w", value, err)
			}
		}
		if at, err := rules.TimeOfMillis(owned["Lease"]["acquiredAt"]); err != nil {
			return nil, fmt.Errorf("upsert Job: the core's Lease.acquiredAt: %w", err)
		} else if at != nil {
			value := types.TemporalDateTime(*at)
			row.LeaseAcquiredAt = &value
		}
		if at, err := rules.TimeOfMillis(owned["Lease"]["renewedAt"]); err != nil {
			return nil, fmt.Errorf("upsert Job: the core's Lease.renewedAt: %w", err)
		} else if at != nil {
			value := types.TemporalDateTime(*at)
			row.LeaseRenewedAt = &value
		}
		if at, err := rules.TimeOfMillis(owned["Lease"]["expiresAt"]); err != nil {
			return nil, fmt.Errorf("upsert Job: the core's Lease.expiresAt: %w", err)
		} else if at != nil {
			value := types.TemporalDateTime(*at)
			row.LeaseExpiresAt = &value
		}
		if value, ok := owned["Lease"]["expiries"]; ok {
			if err := json.Unmarshal(value, &row.LeaseExpiries); err != nil {
				return nil, fmt.Errorf("upsert Job: the core's Lease.expiries %s: %w", value, err)
			}
		}
		if value, ok := owned["Lease"]["ended"]; ok {
			if err := json.Unmarshal(value, &row.LeaseEnded); err != nil {
				return nil, fmt.Errorf("upsert Job: the core's Lease.ended %s: %w", value, err)
			}
		}
		if value, ok := owned["Retries"]["total"]; ok {
			if err := json.Unmarshal(value, &row.RetriesTotal); err != nil {
				return nil, fmt.Errorf("upsert Job: the core's Retries.total %s: %w", value, err)
			}
		}
		if value, ok := owned["Retries"]["classAttempts"]; ok {
			if err := json.Unmarshal(value, &row.RetriesClassAttempts); err != nil {
				return nil, fmt.Errorf("upsert Job: the core's Retries.classAttempts %s: %w", value, err)
			}
		}
		if value, ok := owned["Retries"]["bestScore"]; ok {
			if err := json.Unmarshal(value, &row.RetriesBestScore); err != nil {
				return nil, fmt.Errorf("upsert Job: the core's Retries.bestScore %s: %w", value, err)
			}
		}
		if value, ok := owned["Retries"]["exhausted"]; ok {
			if err := json.Unmarshal(value, &row.RetriesExhausted); err != nil {
				return nil, fmt.Errorf("upsert Job: the core's Retries.exhausted %s: %w", value, err)
			}
		}
		if value, ok := owned["Retries"]["stuck"]; ok {
			if err := json.Unmarshal(value, &row.RetriesStuck); err != nil {
				return nil, fmt.Errorf("upsert Job: the core's Retries.stuck %s: %w", value, err)
			}
		}
		if at, err := rules.TimeOfMillis(owned["Retries"]["retryAt"]); err != nil {
			return nil, fmt.Errorf("upsert Job: the core's Retries.retryAt: %w", err)
		} else if at != nil {
			value := types.TemporalDateTime(*at)
			row.RetriesRetryAt = &value
		}
		if at, err := rules.TimeOfMillis(owned["Retries"]["failingSince"]); err != nil {
			return nil, fmt.Errorf("upsert Job: the core's Retries.failingSince: %w", err)
		} else if at != nil {
			value := types.TemporalDateTime(*at)
			row.RetriesFailingSince = &value
		}
		if value, ok := owned["Retries"]["keyedBy"]; ok {
			if err := json.Unmarshal(value, &row.RetriesKeyedBy); err != nil {
				return nil, fmt.Errorf("upsert Job: the core's Retries.keyedBy %s: %w", value, err)
			}
		}
		if value, ok := owned["status"]["status"]; ok {
			if err := json.Unmarshal(value, &row.Status); err != nil {
				return nil, fmt.Errorf("upsert Job: the core's status.status %s: %w", value, err)
			}
		}
		if at, err := rules.TimeOfMillis(owned["status"]["enteredAt"]); err != nil {
			return nil, fmt.Errorf("upsert Job: the core's status.enteredAt: %w", err)
		} else if at != nil {
			value := types.TemporalDateTime(*at)
			row.StatusEnteredAt = &value
		}
		rows = append(rows, row)
	}
	return rows, nil
}

